<?php
require_once '../config/db.php'; require_once 'auth.php';
if (isset($_GET['delete'])) { $id=(int)$_GET['delete']; if($id>0){ $pdo->beginTransaction(); try { foreach (['attraction_images','travel_tips','itinerary_items'] as $table) { $s=$pdo->prepare("DELETE FROM {$table} WHERE attraction_id=?"); $s->execute([$id]); } $s=$pdo->prepare('DELETE FROM restaurants WHERE attraction_id=?'); $s->execute([$id]); $s=$pdo->prepare('DELETE FROM attractions WHERE attraction_id=?'); $s->execute([$id]); $pdo->commit(); } catch (Throwable $e) { $pdo->rollBack(); throw $e; } } header('Location: attractions.php?deleted=1'); exit; }
$pageTitle='Manage Attractions';
$rows=$pdo->query('SELECT a.*, c.category_name FROM attractions a LEFT JOIN categories c ON c.category_id=a.category_id ORDER BY a.attraction_id DESC')->fetchAll(PDO::FETCH_ASSOC);
include 'header.php';
?><div class="page-actions"><a class="btn" href="attraction_form.php">+ Add Attraction</a></div><?php if(isset($_GET['deleted'])):?><div class="alert success">Attraction deleted successfully.</div><?php endif; ?><section class="card"><div class="table-wrap"><table><thead><tr><th>ID</th><th>Name</th><th>Category</th><th>Location</th><th>Opening Hours</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=$r['attraction_id']?></td><td><strong><?=htmlspecialchars($r['name'])?></strong></td><td><?=htmlspecialchars($r['category_name'] ?? '—')?></td><td><?=htmlspecialchars($r['location'] ?? '—')?></td><td><?=htmlspecialchars($r['opening_hours'] ?? '—')?></td><td class="actions-cell"><a class="btn small" href="attraction_form.php?id=<?=$r['attraction_id']?>">Edit</a><a class="btn small danger-btn" href="attractions.php?delete=<?=$r['attraction_id']?>" onclick="return confirm('Delete this attraction? This action cannot be undone.')">Delete</a></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="6" class="empty">No attractions found.</td></tr><?php endif; ?></tbody></table></div></section><?php include 'footer.php'; ?>
